package kr.danta.core.npc;
import kr.danta.core.diplomacy.*;import kr.danta.core.event.DomainEventBus;import kr.danta.core.nation.NationState;import kr.danta.core.state.GameState;import kr.danta.core.territory.*;import org.junit.jupiter.api.Test;import java.util.Map;import static org.junit.jupiter.api.Assertions.*;
class Dev094NpcPoliticalServiceTest {record F(GameState g,NpcNationService n,DiplomacyService d,NpcPoliticalService p){}F f(){GameState g=new GameState();g.addNation(new NationState("npc","npc"));g.addNation(new NationState("red","red"));g.addStrategicPoint(new StrategicPoint("x","x",StrategicPointType.FARM,"npc",new PointPosition("world",0,64,0),1,Map.of()));NpcNationService n=new NpcNationService(g);n.register("npc");DiplomacyService d=new DiplomacyService(g);return new F(g,n,d,new NpcPoliticalService(g,n,d,new TerritoryService(g,new DomainEventBus())));}
 @Test void allianceKeepsNpcIndependentOwnership(){var f=f();var s=f.p.ally("npc","red");assertEquals(NpcPoliticalStatus.ALLIED,s.politicalStatus());assertEquals("red",s.patronNationId());assertEquals("npc",f.g.strategicPoint("x").orElseThrow().ownerNationId().orElseThrow());}
 @Test void subjugationPreservesNpcTerritory(){var f=f();var s=f.p.subjugate("npc","red");assertEquals(NpcPoliticalStatus.SUBJUGATED,s.politicalStatus());assertEquals("npc",f.g.strategicPoint("x").orElseThrow().ownerNationId().orElseThrow());}
 @Test void annexationTransfersNpcTerritoryAndMarksNationAnnexed(){var f=f();var r=f.p.annex("npc","red");assertEquals(NpcPoliticalStatus.ANNEXED,r.npc().politicalStatus());assertEquals(1,r.transferredPoints());assertEquals("red",f.g.strategicPoint("x").orElseThrow().ownerNationId().orElseThrow());}
}
